  "help.chitInstallments": "अधिकांशः बृहत् चिट् समानमासिकभागस्य (मूल्यं ÷ मासानां) उपयोगं करोति । केचन समूहाः न्यूनतां गच्छन्तीनां किस्तानां (उच्चपूर्वं, न्यूनपश्चात्) उपयोगं कुर्वन्ति । भवतः समूहेन सह सङ्गतं प्रकारं चिनुत ।",
