  "help.chitDiscount": "नीलाम्यां भवान् पूर्णचिट् मूल्यात् न्यूनं स्वीकुर्वति — एषा छूटः अन्यैः सदस्यैः सह साझा भवति । भवन्तः कदापि पूर्णं चिट्-राशिं नगदरूपेण न प्राप्नुवन्ति।",
  "help.chitAdvisor": "मासानां तुलनां करोति यदा भवन्तः चिट् ग्रहीतुं शक्नुवन्ति स्म: अनुमानितं छूटं, फोरमैनस्य अनन्तरं भुक्तिः, तस्मिन् मासे भवतः अन्ये बिलानि, तथा च अधिकतमं हानिः यत् भवन्तः स्वीकुर्वितुं इच्छन्ति।",
  "help.chitMaxLoss": "वयं भवतः आयतः, मासिकं ऋणं, मुक्तऋणं, अतिदेयबिलानि, बचतानि च अधिकतमं हानिं सुचयामः — न तु नियतं % । पूर्वं ग्रहणं प्रायः तस्मात् अतिक्रमति; पश्चात् मासेषु प्रायः न्यूनं मूल्यं भवति ।",
  "help.loanExtraTiming": "आगामिमासान् दर्शयति: यदा अन्ये बिलानि लघुतराणि सन्ति येन भवान् अस्मिन् ऋणे अतिरिक्तं दातुं शक्नोति, तथा च गुरुमासान् यदा भवान् न्यूनतमं धारयितुं अर्हति।",
  "help.incomeEntryBasis": "गृहं नेतुम् करस्य अनन्तरं भवतः बैंके यत् अवतरति तत् मेलयति, () => {\n      const idx = टोकन.पुश (संज्ञा) - 1;\n      return `__T${idx}__`;\n    }, तथा नियत-कटौतिः — दबावस्य मुक्त-नगद-गणितस्य च कृते सर्वोत्तमम् । स्थूलः तदा एव उपयोगी भवति यदा भवता प्रविष्टा प्रत्येकं सङ्ख्या करपूर्वं भवति; मुक्तनगदं भवतः वास्तविकबैङ्कशेषात् न्यूनं दृश्यते यदि गृहं नेतुम् आयः सकलात् न्यूनः भवति।",
