  "sync.accountSyncBullet": "खातासेटिंग्स् (नाम, नगरं, आयः) प्रवेशसमये भवतः Perovo खातेन सह समन्वयं कुर्वन्ति — सर्वेषां कृते निःशुल्कम् ।",
  "sync.dataBackupPaidBullet": "बिल्स्, ऋणं, सम्पत्तिः, सम्झौताः च पेरोवो मेघदत्तांशबैकअपार्थं Pro अथवा Power आवश्यकाः सन्ति ।",
  "sync.backupBullet": "बैकअप इदानीं भवतः वर्तमानदत्तांशं Supabase इत्यत्र रक्षति ।",
