  "sync.autoBullet": "भवता सम्पादनस्य कतिपयेषु सेकेण्ड्-पश्चात् (सक्षम-समये) स्वतः-बैकअपः चाल्यते ।",
  "sync.restoreOnLoginBullet": "नूतने दूरभाषे अथवा रीसेट्-पश्चात् प्रवेशं कुर्वन्तु — भवतः निरन्तरं कृते पूर्वं भवतः नवीनतमं बैकअपं प्रदामः ।",
  "sync.restoreOfferTitle": "भवतः बैकअपं पुनः स्थापयतु?",
