  "profileHub.scoreDetail.fix": "कथं सुधारः करणीयः",
  "profileHub.scorePayOrder": "सुझातः वेतनक्रमः",
  "profileHub.scorePayOrderHint": "यदा नगदं कठिनं भवति तदा प्रथमं अतिदेयानि उच्चव्याजयुक्तानि च बिलानि दातव्यानि।",
  "profileHub.scoreDueBy": "देयम् {date} द्वारा।",
  "profileHub.scoreFix.payFirst": "प्रथमं एतत् दातव्यम्",
  "profileHub.scoreFix.payFirstHint": "अतिदेय / उच्च-व्याज-भारं ​​शीघ्रतमं स्वच्छं करोति।",
  "profileHub.scoreWhy.pressure.what": "भवतः आयस्य कियत् भागं बिलेषु, अतिदेयवस्तूनि च ताडितम् अस्ति इति मापयति।",
  "profileHub.scoreWhy.pressure.high": "आयस्य सापेक्षतया बहवः बिलानि शीघ्रमेव वा अतिदेयानि वा भवन्ति।",
  "profileHub.scoreWhy.pressure.mid": "आयस्य लक्ष्यमाणः भागः पुनरावर्तनीयं बकाया भवति ।",
  "profileHub.scoreWhy.pressure.low": "अधुना आयस्य सापेक्षतया विधेयकाः प्रबन्धनीयाः सन्ति।",
  "profileHub.scoreWhy.health.what": "बिलभारः, भुक्ति-अभ्यासः, बचत-बफरः, ऋण-प्रवृत्तिः च संयोजयति ।",
  "profileHub.scoreWhy.health.low": "भारस्य, बफरस्य, अथवा भुगतानस्य स्थिरतायाः दुर्बलता एतत् अधः आकर्षयति ।",
  "profileHub.scoreWhy.health.mid": "केषुचित् क्षेत्रेषु ठोसः — कतिपयानि आदतयः वा बफराः वा एतत् उत्थापयितुं शक्नुवन्ति स्म ।",
  "profileHub.scoreWhy.health.good": "समग्रतया आदतयः बफराः च स्वस्थाः दृश्यन्ते।",
  "profileHub.scoreWhy.runway.what": "मासाः भवन्तः आवश्यकवस्तूनि आच्छादयितुं शक्नुवन्ति यदि आयः विरामः भवति (तरलबचना + निःशुल्कनगदम्)।",
  "profileHub.scoreWhy.runway.critical": "अतीव कृशः कुशनः — एकः आय-आघातः अवशोषयितुं कठिनः स्यात् ।",
  "profileHub.scoreWhy.runway.thin": "आरामदायकस्य ३–६ मासस्य आरक्षणस्य अधः ।",
  "profileHub.scoreWhy.runway.ok": "धावनमार्गः इदानीं कृते सुरक्षिततरपरिधिषु अस्ति।",
  "profileHub.scoreWhy.flexibility.what": "मासिकं नियतं ऋणं कृत्वा भवतः कियत् स्थानं अस्ति।",
  "profileHub.scoreWhy.flexibility.low": "अधिकांशः आयः पूर्वमेव पुनरावर्तनीयबिलेषु प्रतिबद्धः भवति ।",
  "profileHub.scoreWhy.flexibility.ok": "भवन्तः प्रतिमासं सार्थकं निःशुल्कं नगदं धारयन्ति।",
  "profileHub.scoreWhy.debt.what": "EMI तथा मासिक आयस्य भागरूपेण ऋणस्य भुक्तिः।",
  "profileHub.scoreWhy.debt.high": "EMI भारः भारी अस्ति — नूतनानि ऋणानि नगदप्रवाहं तनावग्रस्ताः भविष्यन्ति।",
  "profileHub.scoreWhy.debt.ok": "ऋणस्य भुक्तिः प्रबन्धनीयपट्टिकायाः ​​अन्तः भवति ।",
  "profileHub.scoreWhy.lending.what": "ऋणदाने भवता दत्तं वा प्राप्तं वा समये एव पुनर्भुक्तिं निरीक्षते।",
  "profileHub.scoreWhy.lending.empty": "अद्यापि ऋणप्रविष्टयः नास्ति — एतत् स्कोरं निर्मातुं सौदान् योजयन्तु, पुनर्भुक्तिं च लॉगं कुर्वन्तु ।",
  "profileHub.scoreWhy.lending.low": "विलम्बेन वा आंशिकरूपेण वा पुनर्भुक्तिः विश्वासं न्यूनीकरोति स्म ।",
  "profileHub.scoreWhy.lending.ok": "पुनर्भुक्ति-इतिहासः विश्वसनीयः दृश्यते ।",
  "profileHub.scoreFix.pressure.clearOverdue": "प्रथमं अतिदेयबिलानि स्वच्छं कुर्वन्तु — ते अस्य स्कोरस्य अधिकं क्षतिं कुर्वन्ति ।",
  "profileHub.scoreFix.pressure.trimSubscriptions": "सदस्यतायाः समीक्षां कुर्वन्तु तथा च वैकल्पिकं EMIs भवन्तः विरामं कर्तुं शक्नुवन्ति।",
  "profileHub.scoreFix.pressure.payOnTime": "दबावं स्थिरं कर्तुं अस्मिन् मासे नियततिथिभ्यः पूर्वं भुङ्क्ते।",
  "profileHub.scoreFix.runway.buildReserve": "प्रत्येकं वेतनदिने द्रवबचने नियतराशिं स्थानान्तरयन्तु।",
  "profileHub.scoreFix.runway.reduceBurn": "धावनमार्गस्य विस्तारार्थं अनावश्यकपुनरावृत्तिबिलानां च्छेदनं कुर्वन्तु।",
  "profileHub.scoreFix.health.reduceBurden": "उच्चभारप्रतिबद्धतां न्यूनीकरोतु वा पुनः समयनिर्धारणं वा कुर्वन्तु।",
  "profileHub.scoreFix.health.buildBuffer": "द्रवबचने ३–६ मासानां व्ययस्य लक्ष्यं कुर्वन्तु।",
  "profileHub.scoreFix.health.payOnTime": "भुक्ति-रेखां रक्षन्तु — प्रत्येकं बिल-देयतां लॉग् कुर्वन्तु ।",
  "profileHub.scoreFix.health.reduceDebt": "प्रथमं उच्चतमव्याजशेषेषु चिप् दूरं कुर्वन्तु।",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
  "profileHub.scoreFix.health.general": "आय, बिल, बचत च लॉगं कुर्वन्तु अतः स्कोराः सटीकाः तिष्ठन्ति।",
  "profileHub.scoreFix.flexibility.reduceBurden": "पुनरावर्तनीयं बकाया न्यूनीकरोतु अथवा यत्र सम्भवं तत्र EMI वार्तालापं कुर्वन्तु।",
  "profileHub.scoreFix.flexibility.trackSpend": "लॉग चर व्ययः अतः मुक्तनगदं वास्तविकतायाः मेलनं करोति।",
