  "wealthDetail.property.holdModerate": "धारयितुं योग्यः — मामूली वास्तविकलाभाः",
  "wealthDetail.property.holdModerateDetail": "नाममात्रवृद्धिः चक्रवृद्धिरूपेण महङ्गानि ताडयति, परन्तु वास्तविकं प्रतिफलं मध्यमं भवति । यदि भवतः तरलतायाः आवश्यकता नास्ति तर्हि धारयतु; विक्रयणं केवलं सशक्तपुनर्निवेशयोजनायाः अथवा जीवन-घटना-नगद-आवश्यकतायाः कृते एव अर्थं करोति ।",
  "wealthDetail.property.holdMature": "परिपक्वः धारः — धनस्य भण्डारः, न तु शीघ्रं नगदः",
  "wealthDetail.property.holdMatureDetail": "You have held long enough to ride multiple cycles. Real returns are positive but modest — this asset works as generational wealth and inflation hedge. Avoid selling unless relocation, debt payoff, or diversification clearly wins after tax and brokerage.",
