  "wealthDetail.property.purchaseThen": "Purchase price (then)",
  "wealthDetail.property.inflationCostToday": "महङ्गानि समायोजितव्ययः (अद्य) २.",
  "wealthDetail.property.inflationCostHint": "न तु भवतः वर्तमानमूल्यं — मूलक्रयणस्य मूल्यं अद्यतनरूप्यकेषु किम् अस्ति ।",
  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "क्रयमूल्यं भवता प्रविष्टस्य दरात् × क्षेत्रात् आगच्छति — यदि कुलम् गलत् दृश्यते तर्हि सम्पादयन्तु इति ट्याप् कुर्वन्तु ।",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "दीर्घधारणाः समयजोखिमं न्यूनीकरोति परन्तु पूंजीं ताडयन्ति — एतत् विक्रयणीयधनरूपेण व्यवहारं कर्तुं पूर्वं ६–१२ मासानां व्ययम् अन्यत्र तरलं स्थापयन्तु ।",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "यदि पूर्णतया किराया भवति तर्हि सकलं किराया भवतः घोषितमासिक-आयस्य ~{pct}% भविष्यति — पश्यन्तु यत् तत् भवतः वास्तविक-वा साध्य-भाडायाः मेलनं करोति वा ।",
  "wealthDetail.property.narrative.valueVsIncome": "इयं सम्पत्तिः ~{multiple}× कागदपत्रे भवतः वार्षिकं आयम् अस्ति — एकः विशालः एकाग्रता; तत् आपत्कालीनविविधतानियोजने कारकं कुर्वन्तु।",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "लघुनगरे अस्मिन् मूल्ये क्रेतारं अन्वेष्टुं मासान् यावत् समयः भवितुं शक्नोति — यथार्थतया मूल्यं भवति तथा च पूर्णमूल्यं तत्क्षणं उपलब्धं नगदरूपेण गणयितुं परिहरन्तु ।",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "टीयर-2 मार्केट् कृते उच्चटिकटम् — स्वस्य उक्तमूल्ये द्रुततरलतां ग्रहीतुं पूर्वं समीपे हाले पञ्जीकृतविक्रयस्य सत्यापनम् कुर्वन्तु ।",
  "wealthDetail.property.narrative.targetCagrReality": "इतः 12% CAGR इत्यस्य अनुसरणं कृत्वा अद्यतनगत्या ~{years} अधिकवर्षं यावत् समयः स्यात् — भवतः धारणा पूर्वमेव सशक्तं नाममात्रलाभं प्रदत्तवती; भविष्यस्य प्रतिफलनं सामान्यं भवितुम् अर्हति।",
  "wealthDetail.property.narrative.landHold": "भूमिः : न्यूनतमं अनुरक्षणं किन्तु मन्दतमं तरलता — 10+ वर्षस्य क्षितिजस्य कृते सर्वोत्तमम्; सूचीकरणात् पूर्वं भारस्य, क्षेत्रीकरणस्य, मार्गविस्तारस्य च सूचनानां जाँचं कुर्वन्तु ।",
  "wealthDetail.property.narrative.commercialHold": "वाणिज्यिकम् : रिक्तस्थानं किरायेदारस्य गुणवत्ता च स्थानवत् महत्त्वपूर्णं भवति — यदि पदप्रहारः अथवा पट्टे शर्ताः दुर्बलाः भवन्ति तर्हि पुनः मूल्याङ्कनं कुर्वन्तु ।",
  "wealthDetail.property.narrative.residentialHold": "आवासीयः : स्वप्रयोगेन विक्रयणस्य दबावः न्यूनीकरोति; यदि किराये भवति तर्हि किरायेदारस्य कारोबारं समाजस्य अनुरक्षणस्य च वृद्धिः निरीक्षते।",
  "wealthDetail.property.narrative.verifyTitle": "कस्यापि विक्रयस्य पूर्वं: भारप्रमाणपत्रं, सम्पत्तिकरस्य रसीदाः, उत्परिवर्तनस्य स्थितिः च — अत्र विलम्बः कागदस्य लाभं मेटयति ।",
